states.999280aa751a:
{
 "call": {
  "company": "Kestrel Motor Company",
  "event": "Q1 2026 earnings call",
  "date": "2026-05-04"
 },
 "release_headline": "Kestrel reports Q1 revenue of $39.6 billion and adjusted EBIT of $1.1 billion; suspends full-year 2026 adjusted EBIT and free cash flow guidance",
 "guidance_given_feb_2026": {
  "adjusted_ebit": "$6.8B to $8.2B",
  "adjusted_free_cash_flow": "$3.2B to $4.2B",
  "capital_spending": "$8.0B to $9.0B"
 },
 "ceo_remarks": "Our team delivered a solid quarter. Pro trucks and vans had their best Q1 in four years, and our warranty cost per unit was down for the third straight quarter. Underneath the headlines, this business is performing the way we told you it would in February. What has changed is the policy environment. It is still too early to see how the new tariffs will move industry pricing and supplier health, so we are pausing the parts of our outlook that depend on those answers.",
 "cfo_remarks": "Let me be precise about the numbers. We now estimate a gross adverse tariff impact of about $2.3 billion for calendar 2026. We have already identified roughly $0.9 billion of offsets, including moving Mexican-built vehicles to Canada in bonded carriers, re-sourcing about 40 part numbers, and targeted pricing, which leaves a net impact of about $1.4 billion. Excluding tariffs, we are tracking to the February ranges for adjusted EBIT and adjusted free cash flow. Because we cannot yet gauge supplier disruption across the industry, we are suspending our full-year adjusted EBIT and adjusted free cash flow guidance. Capital spending is within our control, and we continue to expect $8.0 to $9.0 billion.",
 "qa": [
  {
   "speaker": "Analyst — Priya Venkataraman, Halsey & Crane",
   "text": "Understanding there's uncertainty, can you give us a floor — even a worst-case EBIT number — so the market isn't left guessing?"
  },
  {
   "speaker": "CFO — Tomasz Wierzbicki",
   "text": "I'd rather not put a number out that we might have to walk back in six weeks. What I can tell you is the $1.4 billion net figure, and that we'll update you as soon as the supplier picture is clearer."
  },
  {
   "speaker": "Analyst — Daniel Okafor, Brightline Securities",
   "text": "Is any of this about demand? Are dealers seeing a pull-forward ahead of price increases?"
  },
  {
   "speaker": "CEO — Renata Sølvberg",
   "text": "We did see some pull-forward in April, and we expect that to normalize. But no, the pause is not about demand. Our order bank is healthy."
  }
 ],
 "safe_harbor_note": "Statements about future results are forward-looking and subject to risks described in our most recent Form 10-K and subsequent filings, including trade policy, supplier disruption and commodity prices."
}
